import { Component, Input, inject } from '@angular/core';
import { MessageConfig, MessageService } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';
import { TooltipModule } from 'ngx-bootstrap/tooltip';

export enum Status { active = 'ACTIVE', inactive = 'INACTIVE' }

export interface StatusState {
	color: string;
	label: string | MessageConfig;
	filled?: boolean;
}

export const activeState: StatusState = {
	color: '#008a28',
	label: { key: 'common.status.active' },
	filled: true
};

export const inactiveState: StatusState = {
	color: 'light-dark(#212529, #6c757d)',
	label: { key: 'common.status.inactive' },
	filled: false
};

const unknownState: StatusState = {
	color: '#000000',
	label: 'Unknown',
	filled: false
};

const defaultStates: { [key: string]: StatusState } = {
	[Status.active]: activeState,
	[Status.inactive]: inactiveState
};

@Component({
	selector: 'espd-status-dot',
	imports: [TooltipModule, IconDirective],
	templateUrl: './status-dot.component.html',
	styleUrls: ['./status-dot.component.scss']
})
export class StatusDotComponent {

	@Input()
	public states: { [key: string]: StatusState } = defaultStates;

	@Input()
	public currentValue?: string;

	private messageService = inject(MessageService);

	public get label(): string {
		const label = this.currentState.label;
		return this.messageService.evaluate(label);
	}

	public get color(): string {
		return this.currentState.color;
	}

	public get filled(): boolean {
		return this.currentState.filled || false;
	}

	private get currentState(): StatusState {
		return this.currentValue ? this.states?.[this.currentValue] || unknownState : unknownState;
	}
}
